import React from 'react';
import { LuLibrary } from 'react-icons/lu';

type SimpleShelfIconProps = React.SVGProps<SVGSVGElement> & { size?: number | string };

// The selected "A · Simple shelf": four book spines above a single shelf.
export default function SimpleShelfIcon({ size = '1em', ...props }: SimpleShelfIconProps) {
  return (
    <svg
      xmlns='http://www.w3.org/2000/svg' viewBox='0 0 34 34'
      width={size} height={size} fill='none' stroke='currentColor'
      strokeWidth={2} strokeLinecap='round' strokeLinejoin='round'
      aria-hidden='true' focusable='false' {...props}
    >
      <LuLibrary x={5} y={5} size={24} />
      <path d='M2 31h30' />
    </svg>
  );
}

import React from 'react';
import {
  MdOutlineCloudDownload,
  MdOutlineCloudUpload,
  MdOutlineDelete,
  MdOutlineEdit,
  MdOutlineFileDownload,
  MdOutlineHeadphones,
  MdOutlineLanguage,
  MdOutlinePictureAsPdf,
  MdOutlineStorefront,
  MdPictureAsPdf,
} from 'react-icons/md';
import { GiBoxUnpacking } from 'react-icons/gi';
import SimpleShelfIcon from '@/components/SimpleShelfIcon';

import { Book } from '@/types/book';
import { BookMetadata } from '@/libs/document';
import { useTranslation } from '@/hooks/useTranslation';
import {
  formatAuthors,
  formatDate,
  formatBytes,
  formatLanguage,
  formatPublisher,
  formatTitle,
} from '@/utils/book';
import BookCover from '@/components/BookCover';

interface BookDetailViewProps {
  book: Book;
  metadata: BookMetadata;
  fileSize: number | null;
  onEdit?: () => void;
  onDelete?: () => void;
  onDownload?: () => void;
  onUpload?: () => void;
  onDownloadLocal?: () => void;
  onDownloadBookseller?: () => void;
  onDownloadWebReady?: () => void;
  onDownloadPdf5x8?: () => void;
  onPaperbackCover?: () => void;
  onDownloadPdf?: () => void;
  onDownloadPdfSquare?: () => void;
  onXray?: () => void;
  onAudiobook?: () => void;
  onReadEpub?: () => void;
  onHelp?: () => void;
}

const BookDetailView: React.FC<BookDetailViewProps> = ({
  book,
  metadata,
  fileSize,
  onEdit,
  onDelete,
  onDownload,
  onUpload,
  onDownloadLocal,
  onDownloadBookseller,
  onDownloadWebReady,
  // onDownloadPdf5x8, // Restore with the commented button below if wanted.
  onPaperbackCover,
  onDownloadPdf,
  onDownloadPdfSquare,
  onXray,
  onAudiobook,
  onHelp,
}) => {
  const _ = useTranslation();

  return (
    <div className='relative w-full rounded-lg'>
      <div className='mb-6 me-4 flex min-h-32 items-start'>
        <div className='me-4 sm:me-10 aspect-[28/41] h-32 shadow-lg'>
          <BookCover mode='list' book={book} />
        </div>
        <div className='title-author flex min-h-32 flex-col justify-between'>
          <div>
            <p className='text-base-content mb-2 line-clamp-2 text-lg font-bold'>
              {formatTitle(book.title) || _('Untitled')}
            </p>
            <p className='text-neutral-content line-clamp-1'>
              {formatAuthors(book.author, book.primaryLanguage) || _('Unknown')}
            </p>
          </div>
          <div className='flex items-center gap-x-3 bg-base-200/50 rounded-lg px-3 py-2'>
            {onHelp && (
              <button
                onClick={onHelp}
                title={_('Icon guide')}
                className='border border-base-300 rounded px-2 py-1 text-[11px] text-neutral-content hover:text-base-content font-medium'
              >
                {_('Help')}
              </button>
            )}
            <div className='w-px self-stretch bg-base-300'></div>
            <div className='flex flex-col gap-y-2'>
              <div className='flex flex-wrap items-center gap-x-3 sm:gap-x-8'>
                {onEdit && (
                  <button onClick={onEdit} title={_('Edit Ebook Metadata')}>
                    <MdOutlineEdit className='fill-base-content hover:fill-blue-500' />
                  </button>
                )}
                {onDelete && (
                  <button onClick={onDelete} title={_('Remove ebook')}>
                    <MdOutlineDelete className='fill-red-500 hover:fill-red-600' />
                  </button>
                )}
                {book.uploadedAt && onDownload && (
                  <button onClick={onDownload} title={_('Download from Private Ebooks')}>
                    <MdOutlineCloudDownload className='fill-base-content' />
                  </button>
                )}
                {book.downloadedAt && onUpload && (
                  <button onClick={onUpload} title={_('Back up to Private Ebooks')}>
                    <MdOutlineCloudUpload className='fill-base-content' />
                  </button>
                )}
                {onDownloadLocal && (
                  <button onClick={onDownloadLocal} title={_('Download authors epub')}>
                    <MdOutlineFileDownload className='fill-base-content hover:fill-green-500' />
                  </button>
                )}
                {onDownloadBookseller && (
                  <button onClick={onDownloadBookseller} title={_('Download for booksellers (EPUBCheck-clean)')}>
                    <MdOutlineStorefront className='fill-base-content hover:fill-orange-500' />
                  </button>
                )}
                {onXray && (
                  <button onClick={onXray} title={_('X-ray: View epub structure')}>
                    <GiBoxUnpacking className='fill-base-content hover:fill-purple-500' />
                  </button>
                )}
              </div>
              <div className='flex flex-wrap items-center gap-x-3 sm:gap-x-8'>
                {onDownloadWebReady && (
                  <button onClick={onDownloadWebReady} title={_('Download web ready (zip)')}>
                    <MdOutlineLanguage className='fill-base-content hover:fill-teal-500' />
                  </button>
                )}
                {/* 5x8 button hidden by request; generator and handler remain available.
                {onDownloadPdf5x8 && (
                  <button onClick={onDownloadPdf5x8} title={_('Download 5x8 inch PDF (KDP)')}>
                    <MdPictureAsPdf className='fill-base-content hover:fill-red-400' />
                  </button>
                )}
                */}
                {onPaperbackCover && (
                  <button onClick={onPaperbackCover} title={_('Create 6x9 paperback cover PDF')} aria-label={_('Create 6x9 paperback cover PDF')}>
                    <SimpleShelfIcon className='text-base-content hover:text-amber-600' />
                  </button>
                )}
                {onDownloadPdf && (
                  <button onClick={onDownloadPdf} title={_('Download 6x9 inch PDF (KDP)')}>
                    <MdOutlinePictureAsPdf className='fill-base-content hover:fill-red-500' />
                  </button>
                )}
                {onDownloadPdfSquare && (
                  <button onClick={onDownloadPdfSquare} title={_('Download 8.5x8.5 inch PDF (KDP square)')}>
                    <MdPictureAsPdf className='fill-base-content hover:fill-red-700' />
                  </button>
                )}
                {onAudiobook && (
                  <button onClick={onAudiobook} title={_('Audiobook: Build and play')}>
                    <MdOutlineHeadphones className='fill-base-content hover:fill-amber-500' />
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className='text-base-content my-4'>
        <div className='mb-4 grid grid-cols-2 gap-4 sm:grid-cols-3'>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Publisher')}</span>
            <p className='text-neutral-content text-sm'>
              {formatPublisher(metadata.publisher || '') || _('Unknown')}
            </p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Published')}</span>
            <p className='text-neutral-content text-sm'>
              {formatDate(metadata.published, true) || _('Unknown')}
            </p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Updated')}</span>
            <p className='text-neutral-content text-sm'>{formatDate(book.updatedAt) || ''}</p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Added')}</span>
            <p className='text-neutral-content text-sm'>{formatDate(book.createdAt) || ''}</p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Language')}</span>
            <p className='text-neutral-content text-sm'>
              {formatLanguage(metadata.language) || _('Unknown')}
            </p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Subjects')}</span>
            <p className='text-neutral-content line-clamp-3 text-sm'>
              {formatAuthors(metadata.subject || '') || _('Unknown')}
            </p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('Format')}</span>
            <p className='text-neutral-content text-sm'>{book.format || _('Unknown')}</p>
          </div>
          <div className='overflow-hidden'>
            <span className='font-bold'>{_('File Size')}</span>
            <p className='text-neutral-content text-sm'>{formatBytes(fileSize) || _('Unknown')}</p>
          </div>
        </div>
        <div className='text-neutral-content text-xs font-mono break-all mb-2'>
          {book.hash}
        </div>
        <div>
          <span className='font-bold'>{_('Description')}</span>
          <p
            className='text-neutral-content prose prose-sm max-w-full text-sm'
            dangerouslySetInnerHTML={{
              __html: metadata.description || _('No description available'),
            }}
          ></p>
        </div>
      </div>
    </div>
  );
};

export default BookDetailView;
